import { mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import Database from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import * as schema from "./schema";

/**
 * The single Drizzle connection for the process.
 *
 * Repositories import `db` from `@/server/db` (the barrel), never this module
 * directly, so the connection can be swapped in tests. Never construct a
 * second `Database` — SQLite in WAL mode tolerates it, but the in-process
 * event bus assumes one writer.
 */

const DEFAULT_DB_PATH = "./data/taskflow.db";

let instance: ReturnType<typeof createClient> | null = null;

function createClient(path: string) {
  const absolute = resolve(process.cwd(), path);
  mkdirSync(dirname(absolute), { recursive: true });
  const sqlite = new Database(absolute);
  sqlite.pragma("journal_mode = WAL");
  sqlite.pragma("foreign_keys = ON");
  return drizzle(sqlite, { schema });
}

export function getDb(path: string = process.env.TASKFLOW_DB_PATH ?? DEFAULT_DB_PATH) {
  instance ??= createClient(path);
  return instance;
}

/** Test hook: point the singleton at an in-memory database. */
export function useInMemoryDb(): void {
  instance = createClient(":memory:");
}

export type Db = ReturnType<typeof getDb>;
export type DbSchema = typeof schema;
/**
 * Data-layer entry point. Repositories import `{ getDb }` and the table
 * objects from here so the concrete client module stays swappable.
 */
export { getDb, useInMemoryDb } from "./client";
export type { Db, DbSchema } from "./client";
export * from "./schema";
/**
 * Applies the drizzle-kit migrations in ./drizzle to the SQLite file. Run via `pnpm db:migrate`.
 */
import { existsSync, mkdirSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import Database from "better-sqlite3";

const DEFAULT_DB_PATH = "./data/taskflow.db";
const MIGRATIONS_DIR = "./drizzle";

/**
 * Statements that bring an empty database up to the current schema.
 *
 * `drizzle-kit generate` writes SQL into `./drizzle`, and when that directory
 * exists it is authoritative. It is not checked in — the corpus has to migrate
 * offline from a clean clone — so this is the fallback "push" path, equivalent
 * to `drizzle-kit push` and kept in step with `src/server/db/schema/**`.
 */
const SCHEMA_STATEMENTS: readonly string[] = [
  `CREATE TABLE IF NOT EXISTS users (
     id TEXT PRIMARY KEY NOT NULL,
     email TEXT NOT NULL,
     name TEXT NOT NULL,
     password_hash TEXT NOT NULL,
     avatar_url TEXT,
     timezone TEXT NOT NULL DEFAULT 'UTC',
     email_verified_at TEXT,
     created_at TEXT NOT NULL,
     updated_at TEXT NOT NULL
   )`,
  `CREATE UNIQUE INDEX IF NOT EXISTS users_email_idx ON users (email)`,
  `CREATE TABLE IF NOT EXISTS sessions (
     id TEXT PRIMARY KEY NOT NULL,
     user_id TEXT NOT NULL,
     active_org_id TEXT,
     token_hash TEXT NOT NULL,
     expires_at TEXT NOT NULL,
     created_at TEXT NOT NULL,
     updated_at TEXT NOT NULL
   )`,
  `CREATE UNIQUE INDEX IF NOT EXISTS sessions_token_idx ON sessions (token_hash)`,
  `CREATE TABLE IF NOT EXISTS password_reset_tokens (
     id TEXT PRIMARY KEY NOT NULL,
     user_id TEXT NOT NULL,
     token_hash TEXT NOT NULL,
     expires_at TEXT NOT NULL,
     used_at TEXT,
     created_at TEXT NOT NULL,
     updated_at TEXT NOT NULL
   )`,
  `CREATE TABLE IF NOT EXISTS organizations (
     id TEXT PRIMARY KEY NOT NULL,
     name TEXT NOT NULL,
     slug TEXT NOT NULL,
     owner_id TEXT NOT NULL,
     plan TEXT NOT NULL DEFAULT 'free',
     logo_url TEXT,
     trial_ends_at TEXT,
     default_issue_status TEXT NOT NULL DEFAULT 'backlog',
     allow_public_projects INTEGER NOT NULL DEFAULT 0,
     require_two_factor INTEGER NOT NULL DEFAULT 0,
     digest_hour_utc INTEGER NOT NULL DEFAULT 7,
     enabled_flag_overrides TEXT NOT NULL DEFAULT '[]',
     created_at TEXT NOT NULL,
     updated_at TEXT NOT NULL,
     archived_at TEXT
   )`,
  `CREATE UNIQUE INDEX IF NOT EXISTS organizations_slug_idx ON organizations (slug)`,
  `CREATE INDEX IF NOT EXISTS organizations_owner_idx ON organizations (owner_id)`,
  `CREATE TABLE IF NOT EXISTS organization_usage (
     org_id TEXT PRIMARY KEY NOT NULL,
     seats_used INTEGER NOT NULL DEFAULT 0,
