    const staff = makeActor({ orgId: ORG_B, isPlatformStaff: true, role: "owner" });
    expect(can(staff, "org:read", orgResource)).toBe(false);
    expect(explain(staff, "org:read", orgResource).reason).toBe("denied_cross_tenant");
  });

