import type { OrgId, UserId } from "./common";
import type { PlanId } from "./billing";
import type { Role } from "./member";

/**
 * Every feature flag known to Taskflow. Adding a key here obliges you to add a
 * matching entry to `FEATURE_FLAG_DEFINITIONS` in `src/config/feature-flags.ts`
 * — the type is what keeps the two in sync.
 */
export type FeatureFlagKey =
  | "kanban_board"
  | "ai_issue_summary"
  | "command_palette"
  | "activity_feed"
  | "public_projects"
  | "webhooks"
  | "csv_export"
  | "digest_email"
  | "issue_templates"
  | "advanced_search";

export type FlagRolloutStrategy =
  | { readonly kind: "off" }
  | { readonly kind: "on" }
  | { readonly kind: "plan"; readonly minPlan: PlanId }
  | { readonly kind: "role"; readonly minRole: Role }
  | { readonly kind: "percentage"; readonly percent: number };

export interface FeatureFlagDefinition {
  readonly key: FeatureFlagKey;
/**
 * Barrel for the Zod contract. Client forms import the individual schema they
 * bind to a resolver; Server Actions import the same symbol. Never redeclare a
 * shape locally — extend the schema here instead.
 */
export * from "./common";
export * from "./slug";
export * from "./role";
export * from "./auth";
export * from "./session";
export * from "./organization";
export * from "./member";
export * from "./invitation";
export * from "./project";
export * from "./issue";
export * from "./comment";
export * from "./label";
export * from "./attachment";
export * from "./notification";
export * from "./activity";
export * from "./billing";
export * from "./feature-flag";
export * from "./search";
export * from "./webhook";
export * from "./export";
export * from "./pagination";
import { z } from "zod";
import { orgIdSchema, webhookIdSchema } from "./common";

export const webhookEventTypeSchema = z.enum([
  "issue.created",
  "issue.updated",
  "issue.status_changed",
  "issue.assigned",
  "comment.created",
  "member.joined",
  "project.created",
  "project.archived",
  "billing.plan_changed",
]);

export const createWebhookSchema = z.object({
  orgId: orgIdSchema,
  url: z.url().max(2_000),
  eventTypes: z.array(webhookEventTypeSchema).min(1).max(20),
});

export const updateWebhookSchema = z.object({
  orgId: orgIdSchema,
  webhookId: webhookIdSchema,
  url: z.url().max(2_000).optional(),
  eventTypes: z.array(webhookEventTypeSchema).min(1).max(20).optional(),
  enabled: z.boolean().optional(),
});

export const deleteWebhookSchema = z.object({
  orgId: orgIdSchema,
  webhookId: webhookIdSchema,
});

/** Body accepted by the inbound webhook receiver route handler. */
export const inboundWebhookSchema = z.object({
  source: z.enum(["billing", "email", "ci"]),
  eventId: z.string().min(1).max(128),
  occurredAt: z.iso.datetime(),
  payload: z.record(z.string(), z.unknown()).default({}),
import { index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

export const webhookEndpoints = sqliteTable(
  "webhook_endpoints",
  {
    id: idColumn(),
    ...tenantColumns,
    url: text("url").notNull(),
    secret: text("secret").notNull(),
    /** JSON array of `TaskflowEventType`. */
    eventTypes: text("event_types").notNull().default("[]"),
    enabled: integer("enabled", { mode: "boolean" }).notNull().default(true),
    ...timestampColumns,
  },
  (table) => [index("webhook_endpoints_org_idx").on(table.orgId)],
);

export const webhookDeliveries = sqliteTable(
  "webhook_deliveries",
  {
    id: idColumn(),
    ...tenantColumns,
    endpointId: text("endpoint_id").notNull(),
    eventType: text("event_type").notNull(),
    payload: text("payload").notNull(),
    status: text("status", { enum: ["pending", "delivered", "failed"] })
      .notNull()
      .default("pending"),
    attempts: integer("attempts").notNull().default(0),
    lastError: text("last_error"),
    deliveredAt: text("delivered_at"),
    ...timestampColumns,
  },
  (table) => [
    index("webhook_deliveries_org_status_idx").on(table.orgId, table.status),
  ],
);

/** Token-bucket state for `src/lib/rate-limit.ts`, persisted per org+key. */
export const rateLimitBuckets = sqliteTable(
  "rate_limit_buckets",
  {
    id: idColumn(),
    ...tenantColumns,
    bucketKey: text("bucket_key").notNull(),
    tokens: integer("tokens").notNull(),
    refilledAt: text("refilled_at").notNull(),
  },
  (table) => [index("rate_limit_org_key_idx").on(table.orgId, table.bucketKey)],
);

/** Denormalised full-text index maintained by `SearchService`. */
export const searchIndex = sqliteTable(
  "search_index",
  {
    id: idColumn(),
    ...tenantColumns,
    subjectKind: text("subject_kind", {
      enum: ["issue", "comment", "project"],
    }).notNull(),
    subjectId: text("subject_id").notNull(),
    projectId: text("project_id"),
    content: text("content").notNull(),
    indexedAt: text("indexed_at").notNull(),
  },
  (table) => [
    index("search_index_org_kind_idx").on(table.orgId, table.subjectKind),
  ],
);

export type WebhookEndpointRow = typeof webhookEndpoints.$inferSelect;
export type WebhookDeliveryRow = typeof webhookDeliveries.$inferSelect;
export type SearchIndexRow = typeof searchIndex.$inferSelect;

