import type { IsoTimestamp, OrgId, UserId } from "./common";

/**
 * What a personal API token may do. A `read` token always authenticates as a
 * viewer; a `write` token carries its owner's current role.
 */
export type ApiTokenScope = "read" | "write";

/**
 * A personal API token as the rest of the app sees it. Never carries the
 * secret or its hash — the secret is shown once, by `createApiToken`, and only
 * its hash is stored.
 */
export interface ApiToken {
  id: string;
  orgId: OrgId;
  userId: UserId;
  name: string;
  scope: ApiTokenScope;
  /** The first characters of the secret, so a user can tell tokens apart. */
  prefix: string;
  expiresAt: IsoTimestamp;
  lastUsedAt: IsoTimestamp | null;
  revokedAt: IsoTimestamp | null;
  createdAt: IsoTimestamp;
}

