/**
 * Personal API token rows. Stores only the hash of the secret; revocation is a
 * `revoked_at` stamp, never a delete.
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

export interface NewApiToken {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly prefix: string;
  readonly tokenHash: string;
  readonly expiresAt: IsoTimestamp;
  readonly createdAt: IsoTimestamp;
}

/** Not revoked and not yet expired at `now`. */
function usablePredicate(now: IsoTimestamp) {
  return and(isNull(apiTokens.revokedAt), gt(apiTokens.expiresAt, now));
}

/**
 * Inserts the token unless its user already holds `limit` usable tokens in
 * the org, in which case nothing is written and `null` comes back. The count
 * and the insert share one synchronous transaction, so two concurrent creates
 * cannot both slip under the limit.
 */
export async function insertApiTokenWithinLimit(
  token: NewApiToken,
  limit: number,
): Promise<ApiToken | null> {
  return getDb().transaction((tx) => {
    const usable = tx
      .select({ value: count() })
      .from(apiTokens)
      .where(
        and(
          orgPredicate(apiTokens.orgId, token.orgId),
          eq(apiTokens.userId, token.userId),
          usablePredicate(token.createdAt),
        ),
      )
      .get();

    if ((usable?.value ?? 0) >= limit) return null;

    const row = tx
      .insert(apiTokens)
      .values({
        id: newId(),
        orgId: token.orgId,
        userId: token.userId,
        name: token.name,
        scope: token.scope,
        prefix: token.prefix,
        tokenHash: token.tokenHash,
        expiresAt: token.expiresAt,
        lastUsedAt: null,
        revokedAt: null,
        createdAt: token.createdAt,
        updatedAt: token.createdAt,
      })
      .returning()
      .get();

    return toApiToken(row);
  });
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/**
 * The authentication lookup. Global rather than org-scoped: the presented
 * secret is the only thing the caller has, and it names its own org.
 */
export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

/**
 * Every token the user holds in the org, revoked and expired included, newest
 * first. `rowid` breaks ties between tokens created in the same millisecond.
 */
export async function listApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)))
    .orderBy(desc(apiTokens.createdAt), desc(sql`rowid`))
    .all();
  return rows.map(toApiToken);
}

/**
 * Stamps `revoked_at` on a live token. Returns `null` when the token does not
 * exist or was already revoked — the original stamp is never overwritten.
 */
export async function revokeApiToken(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();
  return row ? toApiToken(row) : null;
}

/**
 * Revokes every not-yet-revoked token (expired ones included) the user holds
 * in the org; returns exactly the rows this call revoked.
 */
export async function revokeTokensForUser(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .update(apiTokens)
    .set({ revokedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .all();
  return rows.map(toApiToken);
}

/**
 * Records a successful authentication. Only a still-usable token is touched;
 * `false` means it was revoked or expired in the meantime.
 */
export async function touchLastUsed(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<boolean> {
  const row = getDb()
    .update(apiTokens)
    .set({ lastUsedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        usablePredicate(at),
      ),
    )
    .returning({ id: apiTokens.id })
    .get();
  return row !== undefined;
}

