/**
 * Personal API tokens: minting, listing and revoking them, and turning a presented secret back into an `Actor`.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, subscribe, hashToken, randomToken, resolveActor
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { createApiTokenSchema } from "@/schemas/api-token";
import { toIsoTimestamp } from "@/types/common";
import { resolveActor } from "./member-service";
import {
  actorEnvelope,
  apiTokenResource,
  envelope,
  requireFound,
} from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

/** Every secret starts with this, so a leaked one is recognisable in logs. */
export const API_TOKEN_SECRET_PREFIX = "tfk_";

/** How much of the secret is kept in clear, to tell tokens apart in the UI. */
const DISPLAY_PREFIX_LENGTH = 12;

/** Usable (unrevoked, unexpired) tokens one user may hold per organization. */
export const MAX_USABLE_TOKENS_PER_USER = 5;

const DAY_MS = 24 * 60 * 60 * 1000;

/**
 * Mints a token for the actor in their own organization. The secret is
 * returned here and nowhere else — only its hash is stored.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);
  assertCan(
    actor,
    parsed.scope === "write" ? "api_token:create_write" : "api_token:create",
    apiTokenResource(parsed.orgId, actor.userId),
  );

  const token = `${API_TOKEN_SECRET_PREFIX}${randomToken()}`;
  const now = new Date();

  const apiToken = await apiTokenRepo.insertApiTokenWithinLimit(
    {
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, DISPLAY_PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(
        new Date(now.getTime() + parsed.expiresInDays * DAY_MS),
      ),
      createdAt: toIsoTimestamp(now),
    },
    MAX_USABLE_TOKENS_PER_USER,
  );

  if (apiToken === null) {
    throw new Error(
      `You already have ${MAX_USABLE_TOKENS_PER_USER} active API tokens in this organization; revoke one first`,
    );
  }

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
    expiresAt: apiToken.expiresAt,
  });

  return { token, apiToken };
}

/**
 * One user's tokens in the org, revoked and expired included, newest first.
 * Anyone may list their own; listing someone else's is an admin's call.
 */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "api_token:read", apiTokenResource(orgId, userId));
  return apiTokenRepo.listApiTokensForUser(orgId, userId);
}

/**
 * Revokes a token. Idempotent: an already-revoked token comes back unchanged
 * and nothing new is audited.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  assertCan(
    actor,
    "api_token:revoke",
    apiTokenResource(existing.orgId, existing.userId),
